
-- Vault stores the Supabase project's existing public anon JWT; no secret in the codebase.
-- All push messages are generated by server-side database events, never request bodies.
create or replace function trade_private.tradarr_dispatch_push_http()
returns bigint language plpgsql security definer set search_path='' as $$
declare
  anon_jwt text;
  req_id bigint;
begin
  if not exists(
    select 1 from public.tradarr_push_outbox
    where (status in ('pending','retry') and next_attempt_at<=now())
       or (status='processing' and processed_at<now()-interval '5 minutes')
  ) then
    return null;
  end if;
  select decrypted_secret into anon_jwt
  from vault.decrypted_secrets where name='tradarr_push_anon_jwt' limit 1;
  if coalesce(anon_jwt,'')='' then
    raise warning 'Tradarr push webhook credential is unavailable; outbox remains pending.';
    return null;
  end if;
  select net.http_post(
    url:='https://sjwedfdwqxfrnpruiqnq.supabase.co/functions/v1/tradarr-push-dispatch',
    headers:=jsonb_build_object(
      'content-type','application/json',
      'authorization','Bearer '||anon_jwt,
      'apikey',anon_jwt
    ),
    body:='{}'::jsonb,
    timeout_milliseconds:=15000
  ) into req_id;
  return req_id;
exception when others then
  -- Never abort a customer's real job or message just because push is unavailable.
  raise warning 'Tradarr push dispatch wake-up failed: %',sqlerrm;
  return null;
end $$;
revoke all on function trade_private.tradarr_dispatch_push_http() from public,anon,authenticated;

create or replace function trade_private.tradarr_wake_push_trigger()
returns trigger language plpgsql security definer set search_path='' as $$
begin
  perform trade_private.tradarr_dispatch_push_http();
  return null;
end $$;
revoke all on function trade_private.tradarr_wake_push_trigger() from public,anon,authenticated;
drop trigger if exists tradarr_push_outbox_webhook on public.tradarr_push_outbox;
create trigger tradarr_push_outbox_webhook after insert on public.tradarr_push_outbox
for each row execute function trade_private.tradarr_wake_push_trigger();

-- Catch transient HTTP errors and abandoned in-progress claims without client activity.
select cron.schedule(
  'tradarr-push-retry-5min','*/5 * * * *',
  'select trade_private.tradarr_dispatch_push_http();'
);

